\title{A Power-of-Two Characterization of\\ Pairwise Reflection Symmetric Latin Squares}
\author{Aristotle}
\date{2026-07-13}

\begin{document}
\maketitle

\begin{abstract}
We study Latin squares that are \emph{pairwise reflection symmetric} (PRS):
arrays in which, on every pair of columns, each ordered pair of symbols $(p,q)$
occurs on exactly as many rows as its reversal $(q,p)$. Restricting to squares of
index $\lambda = 1$ (no ordered symbol pair repeats across two distinct columns),
we establish a complete cross-domain characterization for the fundamental class of
squares arising from finite groups, together with the constructive half of the
general conjecture. We prove that the multiplication (Cayley) table of a finite
group is a Latin square of index one; that this table is pairwise reflection
symmetric \emph{if and only if the group has exponent two} ($x^2 = e$ for all
$x$); that a finite group of exponent two has order a power of two; and,
conversely, that the elementary abelian $2$-groups $(\ZZ/2)^k$ realize a PRS
index-one Latin square of every order $2^k$. Combining these results: a
group-based PRS index-one Latin square of order $n$ exists if and only if $n$ is a
power of two. The equivalence links combinatorial design theory, finite group
theory, and elementary number theory through a single algebraic pivot, the
exponent-two condition. We discuss the remaining open direction (arbitrary,
non-group PRS squares) and several avenues toward it.
\end{abstract}

\medskip
\noindent\textbf{Keywords.} Latin square, reflection symmetry, Cayley table,
exponent-two group, elementary abelian $2$-group, $p$-group, power of two.

\section{Introduction}

A \emph{Latin square of order $n$} is an $n \times n$ array over an $n$-element
symbol set in which every symbol occurs exactly once in each row and exactly once
in each column. Latin squares are central to combinatorial design theory, with
applications spanning experimental design, tournament scheduling, error-correcting
codes, and symmetric-key cryptography.

Beyond the row/column constraint one may impose symmetry conditions on how pairs
of columns interact. Fix two columns and read them together across all rows; each
row yields an ordered pair of symbols. A square is \textbf{pairwise reflection
symmetric} if, for every choice of two columns, the distribution of ordered symbol
pairs is invariant under swapping the two coordinates. This paper concerns the
following conjecture.

\begin{quote}
\textbf{Conjecture.} A pairwise reflection symmetric Latin square of order $n$
with index $\lambda = 1$ exists if and only if $n$ is a power of two.
\end{quote}

Our contribution is a complete proof of this conjecture for the class of squares
obtained from finite groups, together with the constructive (``if'') direction in
full generality. The mechanism is a clean equivalence between a combinatorial
symmetry and an algebraic one.

\section{Definitions}

Throughout, $\alpha$ is a finite set of symbols with $|\alpha| = n$; rows and
columns are indexed by $\alpha$. A square array is a function
$L : \alpha \times \alpha \to \alpha$, with $L(i,j)$ the entry in row $i$, column
$j$.

\begin{definition}[Latin square]
$L$ is a \emph{Latin square} if every row map $j \mapsto L(i,j)$ and every column
map $i \mapsto L(i,j)$ is a bijection of $\alpha$; equivalently, every symbol
occurs exactly once in each row and each column.
\end{definition}

\begin{definition}[Pair count]
For columns $j_1, j_2$ and symbols $p, q$,
\[
\pcount_L(j_1, j_2, p, q) = \bigl|\{\, i \in \alpha : L(i,j_1) = p \text{ and } L(i,j_2) = q \,\}\bigr|.
\]
\end{definition}

\begin{definition}[Pairwise reflection symmetry]
$L$ is \emph{pairwise reflection symmetric} (PRS) if
$\pcount_L(j_1, j_2, p, q) = \pcount_L(j_1, j_2, q, p)$ for all
$j_1, j_2, p, q \in \alpha$.
\end{definition}

\begin{definition}[Index $\le 1$]
$L$ has \emph{index at most one} if for all distinct columns $j_1 \ne j_2$ the map
$i \mapsto (L(i,j_1), L(i,j_2))$ is injective; i.e. no ordered symbol pair repeats
across two distinct columns.
\end{definition}

\begin{definition}[Cayley table]
For a finite group $G$ with product $\cdot$, the \emph{Cayley table} is
$C_G(i,j) = i \cdot j$.
\end{definition}

\begin{definition}[Exponent two]
A group $G$ has \emph{exponent two} if $x \cdot x = e$ for every $x \in G$;
equivalently every element is an involution.
\end{definition}

\section{Cayley tables are index-one Latin squares}

\begin{proposition}
For any finite group $G$, the Cayley table $C_G$ is a Latin square.
\end{proposition}
\begin{proof}
The row map $j \mapsto i \cdot j$ is left multiplication by $i$, a bijection with
inverse left multiplication by $i^{-1}$; the column map $i \mapsto i \cdot j$ is
right multiplication by $j$, likewise a bijection.
\end{proof}

\begin{proposition}[Index one]
For any finite group $G$, the Cayley table $C_G$ has index at most one.
\end{proposition}
\begin{proof}
If $(a \cdot j_1, a \cdot j_2) = (b \cdot j_1, b \cdot j_2)$, then
$a \cdot j_1 = b \cdot j_1$ and right cancellation gives $a = b$.
\end{proof}

\begin{lemma}[Exact pair count]\label{lem:paircount}
For a finite group $G$ and any $j_1, j_2, p, q \in G$,
\[
\pcount_{C_G}(j_1, j_2, p, q) =
\begin{cases}
1 & \text{if } p \cdot j_1^{-1} \cdot j_2 = q,\\
0 & \text{otherwise.}
\end{cases}
\]
\end{lemma}
\begin{proof}
A row $i$ contributes iff $i \cdot j_1 = p$ and $i \cdot j_2 = q$. The first has
the unique solution $i = p \cdot j_1^{-1}$; substituting, the row exists iff
$(p \cdot j_1^{-1}) \cdot j_2 = q$, and is then unique.
\end{proof}

\section{The keystone: reflection symmetry $\iff$ exponent two}

\begin{lemma}\label{lem:abelian}
If $G$ has exponent two, then $x^{-1} = x$ for all $x$, and $G$ is abelian.
\end{lemma}
\begin{proof}
$x \cdot x = e$ gives $x^{-1} = x$. Then
$(a \cdot b)^{-1} = a \cdot b$ while also
$(a \cdot b)^{-1} = b^{-1} \cdot a^{-1} = b \cdot a$, so
$a \cdot b = b \cdot a$.
\end{proof}

\begin{theorem}[Keystone equivalence]\label{thm:keystone}
Let $G$ be a finite group. The Cayley table $C_G$ is pairwise reflection
symmetric if and only if $G$ has exponent two.
\end{theorem}
\begin{proof}
Write $w = j_1^{-1} \cdot j_2$. By Lemma~\ref{lem:paircount},
$\pcount_{C_G}(j_1, j_2, p, q) = \mathbf{1}[\,p \cdot w = q\,]$ and
$\pcount_{C_G}(j_1, j_2, q, p) = \mathbf{1}[\,q \cdot w = p\,]$, using
$p \cdot j_1^{-1} \cdot j_2 = p \cdot w$.

\emph{($\Leftarrow$)} If $w \cdot w = e$ and $p \cdot w = q$, then
$q \cdot w = (p \cdot w) \cdot w = p \cdot (w \cdot w) = p$, and symmetrically;
so the indicators agree and $C_G$ is PRS.

\emph{($\Rightarrow$)} Fix $x$ and take $j_1 = e$, $j_2 = x$, $p = e$, $q = x$, so
$w = x$. The $(p,q)$ condition $e \cdot x = x$ holds, giving count $1$; by PRS the
reversed count is $1$, i.e. $q \cdot w = p$ reads $x \cdot x = e$. As $x$ was
arbitrary, $G$ has exponent two.
\end{proof}

\section{From exponent two to powers of two}

\begin{theorem}[$2$-group theorem]\label{thm:2group}
A finite group $G$ of exponent two has order a power of two.
\end{theorem}
\begin{proof}
Every $g \in G$ satisfies $g^2 = e$, so its order divides $2$ and is a power of
the prime $2$. Hence $G$ is a finite $2$-group, and by the structure theorem for
finite $p$-groups $|G| = 2^k$ for some $k \ge 0$.
\end{proof}

\begin{corollary}
If the Cayley table of a finite group $G$ is pairwise reflection symmetric, then
$|G|$ is a power of two.
\end{corollary}

\begin{theorem}[Existence of exponent-two groups]\label{thm:existence}
For $n \in \NN$, a finite group of order $n$ and exponent two exists if and only
if $n$ is a power of two.
\end{theorem}
\begin{proof}
($\Rightarrow$) Theorem~\ref{thm:2group}. ($\Leftarrow$) For $n = 2^k$, the group
$(\ZZ/2)^k$ has order $2^k$ and $x + x = 0$ for all $x$.
\end{proof}

\begin{theorem}[Characterization for group tables]\label{thm:main}
For a finite group $G$ of order $n$, the Cayley table $C_G$ is a pairwise
reflection symmetric Latin square of index one if and only if $n$ is a power of
two. Moreover every power of two is realized.
\end{theorem}
\begin{proof}
$C_G$ is always a Latin square of index one; it is PRS iff $G$ has exponent two
(Theorem~\ref{thm:keystone}), which holds iff $n$ is a power of two
(Theorem~\ref{thm:existence}); realization is by $(\ZZ/2)^k$.
\end{proof}

\section{Construction: the elementary abelian witnesses}

\begin{theorem}[Constructive direction]
For every $k \in \NN$ there exists a Latin square of order $2^k$ that is pairwise
reflection symmetric and has index one.
\end{theorem}
\begin{proof}
Take $\alpha = (\ZZ/2)^k$ under coordinatewise addition mod $2$ and let
$L(i,j) = i + j$. Then $|\alpha| = 2^k$; $L$ is an index-one Latin square; and
$x + x = 0$ gives exponent two, so $L$ is PRS by Theorem~\ref{thm:keystone}.
\end{proof}

\begin{remark}
For $k = 1, 2, 3$ the witnesses are the one-, two-, and three-bit XOR tables of
orders $2$, $4$, $8$ --- the addition tables ubiquitous in coding theory and
symmetric cryptography.
\end{remark}

\section{Discussion and future directions}

For squares arising as group Cayley tables the conjecture is completely proven in
both directions (Theorem~\ref{thm:main}); the constructive half holds in full
generality. The engine is Theorem~\ref{thm:keystone}, converting the column-pair
reflection condition into the exponent-two identity and thence into the arithmetic
of $2$-groups.

The open part is the ``only if'' direction for \emph{arbitrary} PRS index-one
squares: if such a square of order $n$ exists, must $n$ be a power of two? The
obstruction is that not every Latin square is a group table --- the smallest
non-group example already appears at order five. Avenues: (i) autotopism /
difference invariants, seeking an $\FF_2$-linear invariant of the column-pair
transition permutations that survives for non-group squares; (ii) a quasigroup
formulation in which exponent two generalizes to a Steiner-like identity forcing
$|Q| = 2^k$; (iii) a character/Fourier method extending the $\pm 1$-character
description of the abelian case.

The definitions of Latin square, pair count, pairwise reflection symmetry, index
$\le 1$, and the Cayley pair-count formula are generic and support future work on
symmetric Latin squares of any origin.

\end{document}

