"""
Verify the exact Cayley pair-count formula numerically.

Claim: for a finite group G and any j1, j2, p, q,
    pairCount(C_G; j1, j2, p, q) = 1  if  p * j1^{-1} * j2 = q,  else 0.

We check this identity element-by-element for several groups.
"""
from __future__ import annotations
from itertools import product
from typing import Callable, Dict, List, Tuple


def build_group_ops(elements: List[object], mul: Callable[[object, object], object],
                    identity: object):
    inv: Dict[object, object] = {}
    for a in elements:
        for b in elements:
            if mul(a, b) == identity:
                inv[a] = b
                break
    return inv


def cayley_pair_count(elements, mul, j1, j2, p, q) -> int:
    return sum(1 for i in elements if mul(i, j1) == p and mul(i, j2) == q)


def formula_value(mul, inv, j1, j2, p, q) -> int:
    return 1 if mul(mul(p, inv[j1]), j2) == q else 0


def check_group(name: str, elements, mul, identity) -> bool:
    inv = build_group_ops(elements, mul, identity)
    ok = True
    for j1, j2, p, q in product(elements, repeat=4):
        lhs = cayley_pair_count(elements, mul, j1, j2, p, q)
        rhs = formula_value(mul, inv, j1, j2, p, q)
        if lhs != rhs:
            ok = False
            print(f"  MISMATCH {name}: {(j1, j2, p, q)} lhs={lhs} rhs={rhs}")
    print(f"{name}: pair-count formula holds = {ok}")
    return ok


if __name__ == "__main__":
    # Z/n
    for n in (3, 4, 5):
        els = list(range(n))
        check_group(f"Z/{n}", els, lambda a, b, n=n: (a + b) % n, 0)
    # (Z/2)^2
    els = list(product((0, 1), repeat=2))
    check_group("(Z/2)^2", els, lambda a, b: tuple(x ^ y for x, y in zip(a, b)), (0, 0))

