function IS_PRS(L, n):
  for j1 in 0..n-1:
    for j2 in 0..n-1:
      for p in 0..n-1:
        for q in 0..n-1:
          c1 = |{ i : L[i][j1]=p and L[i][j2]=q }|
          c2 = |{ i : L[i][j1]=q and L[i][j2]=p }|
          if c1 != c2: return False
  return True

function CAYLEY_TABLE(elements, mul):
  index = { g -> i for i,g in enumerate(elements) }
  T = new n x n array
  for a in elements:
    for b in elements:
      T[index[a]][index[b]] = index[ mul(a,b) ]
  return T

function XOR_PRS_SQUARE(k):
  n = 2^k
  T = new n x n array
  for i in 0..n-1:
    for j in 0..n-1:
      T[i][j] = i XOR j
  return T

